<script lang="ts" module>import type { Snippet } from 'svelte'; import type { RxColor } from '$lib/registry/lib/color'; export interface TabsProps { value?:string; orientation?:'horizontal'|'vertical'; activationMode?:'automatic'|'manual'; color?:RxColor; variant?:'default'|'bubble'|'card'|'chrome'|'gooey'|'neon'; size?:'sm'|'md'|'lg'; radius?:'none'|'subtle'|'rounded'|'pill'|'squircle'; block?:boolean; onValueChange?:(value:string)=>void; children:Snippet; }</script>
<script lang="ts">import { Tabs as Primitive } from 'bits-ui'; import { styleColor } from '$lib/registry/lib/color'; import { setTabsContext } from './context'; let {value=$bindable(''),orientation='horizontal',activationMode='automatic',color,variant='default',size='md',radius='pill',block=false,onValueChange,children}:TabsProps=$props(); setTabsContext({get variant(){return variant},get orientation(){return orientation}}); function changed(v:string){value=v;onValueChange?.(v)}</script>
